          { type: "match", q: "Paragraph that describes efforts to record and revive dying languages", options: ["Paragraph 1", "Paragraph 2", "Paragraph 3", "Paragraph 4", "Paragraph 5", "Paragraph 6", "Paragraph 7"], answer: 5 }
