          { type: "mcq", q: "Why can the destruction of a single site affect an entire migration?", options: ["Because animals never return to the same place", "Because migrating animals depend on a connected chain of habitats", "Because animals only feed at one site", "Because migration does not require energy"], answer: 1 },
          { type: "mcq", q: "According to the final paragraph, why is international cooperation needed to protect migratory species?", options: ["Because they are dangerous to humans", "Because they cross borders and depend on distant, connected sites", "Because they are too numerous to count", "Because they never leave one country"], answer: 1 },
          { type: "match", q: "Paragraph that gives examples of the remarkable precision of some migrations", options: ["Paragraph 1", "Paragraph 2", "Paragraph 3", "Paragraph 4", "Paragraph 5", "Paragraph 6", "Paragraph 7"], answer: 3 }
